new = '''class _Program(object):
    """A fixed constraint set in one z3 context, answered by fresh solvers.

    Every single query rebuilds a solver: answering many bound queries with
    one Solver object that pushes and pops makes z3 dramatically slower, while
    re-asserting a few hundred constraints per query is cheap.
    """

    def __init__(self, ctx):
        self.ctx = ctx
        self.cons = []

    def add(self, cons):
        self.cons.extend(cons)

    def model(self, extra=()):
        """Model of the constraints plus extras, or None if unsatisfiable."""
        sol = z3.Solver(ctx=self.ctx)
        if self.cons:
            sol.add(self.cons)
        if extra:
            sol.add(extra)
        res = sol.check()
        if res == z3.unknown:
            raise RuntimeError('z3 returned unknown')
        return sol.model() if res == z3.sat else None

    def sat(self, extra=()):
        return self.model(extra) is not None

    def minimize(self, expr, low, cur):
        """Least value of expr; ``low`` bounds it from below, ``cur`` attains."""
        if cur <= low:
            return cur
        if self.model([expr <= low]) is not None:
            return low
        best = cur
        lo = low + 1
        while lo < best:
            mid = (lo + best) // 2
            model = self.model([expr <= mid])
            if model is not None:
                value = model.eval(expr, model_completion=True).as_long()
                if value < best:
                    best = value
            else:
                lo = mid + 1
        return best

    def maximize(self, expr, high, cur):
        """Greatest value of expr; ``high`` bounds it, ``cur`` attains."""
        if cur >= high:
            return cur
        if self.model([expr >= high]) is not None:
            return high
        best = cur
        hi = high - 1
        while hi > best:
            mid = (best + hi + 1) // 2
            model = self.model([expr >= mid])
            if model is not None:
                value = model.eval(expr, model_completion=True).as_long()
                if value > best:
                    best = value
            else:
                hi = mid - 1
        return best'''
